FIREBASE_API_KEY = "SUA_API_KEY_AQUI"
FIREBASE_PROJECT_ID = "SEU_PROJECT_ID_AQUI"

class FirebaseClient:
    def __init__(self, api_key, project_id):
        self.api_key = api_key
        self.project_id = project_id
        self.id_token = None
        self.email = None
        
    def login(self, email, password):
        url = f"https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key={self.api_key}"
        payload = {
            "email": email,
            "password": password,
            "returnSecureToken": True
        }
        try:
            res = requests.post(url, json=payload)
            data = res.json()
            if "error" in data:
                return False, data["error"]["message"]
                
            self.id_token = data["idToken"]
            self.email = email
            return True, "Login OK"
        except Exception as e:
            return False, str(e)
        
    def check_access(self):
        if not self.id_token: return False
        url = f"https://firestore.googleapis.com/v1/projects/{self.project_id}/databases/(default)/documents/users/{self.email.lower()}?key={self.api_key}"
        headers = {"Authorization": f"Bearer {self.id_token}"}
        try:
            res = requests.get(url, headers=headers)
            data = res.json()
            if "error" in data:
                return False
                
            fields = data.get("fields", {})
            has_access = fields.get("hasAccess", {}).get("booleanValue", False)
            return has_access
        except:
            return False
        
    def get_voices(self):
        if not self.id_token: return []
        url = f"https://firestore.googleapis.com/v1/projects/{self.project_id}/databases/(default)/documents/voices?key={self.api_key}"
        headers = {"Authorization": f"Bearer {self.id_token}"}
        try:
            res = requests.get(url, headers=headers)
            data = res.json()
            if "error" in data: return []
            
            voices = []
            for doc in data.get("documents", []):
                fields = doc.get("fields", {})
                name = fields.get("name", {}).get("stringValue", "Voz")
                lang = fields.get("language", {}).get("stringValue", "Auto")
                audio_url = fields.get("audio_url", {}).get("stringValue", "")
                voices.append({"name": name, "language": lang, "audio_url": audio_url})
            return voices
        except:
            return []

    def check_is_admin(self):
        if not self.id_token: return False
        url = f"https://firestore.googleapis.com/v1/projects/{self.project_id}/databases/(default)/documents/users/{self.email.lower()}?key={self.api_key}"
        headers = {"Authorization": f"Bearer {self.id_token}"}
        try:
            res = requests.get(url, headers=headers)
            data = res.json()
            if "error" in data: return False
            fields = data.get("fields", {})
            return fields.get("role", {}).get("stringValue", "") == "admin"
        except:
            return False

    def create_voice(self, name, lang, audio_url, gender=""):
        if not self.id_token: return False
        url = f"https://firestore.googleapis.com/v1/projects/{self.project_id}/databases/(default)/documents/voices?key={self.api_key}"
        headers = {"Authorization": f"Bearer {self.id_token}"}
        payload = {
            "fields": {
                "name": {"stringValue": name},
                "language": {"stringValue": lang},
                "audio_url": {"stringValue": audio_url},
                "gender": {"stringValue": gender}
            }
        }
        res = requests.post(url, headers=headers, json=payload)
        return "error" not in res.json()
    def change_password(self, new_password):
        if not self.id_token: return False, "Usuário não autenticado."
        url = f"https://identitytoolkit.googleapis.com/v1/accounts:update?key={self.api_key}"
        payload = {
            "idToken": self.id_token,
            "password": new_password,
            "returnSecureToken": True
        }
        try:
            res = requests.post(url, json=payload)
            data = res.json()
            if "error" in data:
                return False, data["error"]["message"]
            return True, "Senha alterada com sucesso!"
        except Exception as e:
            return False, str(e)


# Instância Global
fb_client = FirebaseClient(FIREBASE_API_KEY, FIREBASE_PROJECT_ID)

GLOBAL_VOICES_CACHE = []
GLOBAL_VOICE_URLS = {}

def do_login(email, pwd):
    global GLOBAL_VOICES_CACHE, GLOBAL_VOICE_URLS
    success, msg = fb_client.login(email, pwd)
    if not success:
                return gr.update(visible=True), gr.update(visible=False), gr.update(visible=False), f"<div style='color:red;'>Erro: {msg}</div>", gr.update(choices=[]), gr.update(choices=[]), gr.update(choices=[]), gr.update(choices=[]), gr.update(choices=[]), gr.update(choices=[])
    
    if not fb_client.check_access():
                return gr.update(visible=True), gr.update(visible=False), gr.update(visible=False), "<div style='color:orange;'>Sem acesso. Por favor, compre na Kiwify.</div>", gr.update(choices=[]), gr.update(choices=[]), gr.update(choices=[]), gr.update(choices=[]), gr.update(choices=[]), gr.update(choices=[])
        
    voices = fb_client.get_voices()
    voices = sorted(voices, key=lambda x: x.get('name', '').lower())
    GLOBAL_VOICES_CACHE = voices
    
    langs = sorted(list(set([v.get('language', 'Outros') for v in voices])))
    
    for v in voices:
        g = f" - {v.get('gender')}" if v.get('gender') else ""
        display_name = f"{v['name']} ({v['language']}{g})"
        GLOBAL_VOICE_URLS[display_name] = v['audio_url']
        
    voice_choices = []
    for v in voices:
        g = f" - {v.get('gender')}" if v.get('gender') else ""
        voice_choices.append(f"{v['name']} ({v['language']}{g})")
    
    is_admin = fb_client.check_is_admin()
    
    up1 = gr.update(visible=True, choices=["Todos os Idiomas"] + langs, value="Todos os Idiomas")
    up2 = gr.update(visible=True, choices=["Nenhuma (Fazer Upload)"] + voice_choices, value="Nenhuma (Fazer Upload)")
    return gr.update(visible=False), gr.update(visible=True), gr.update(visible=is_admin), "<div style='color:green;'>Login Sucesso!</div>", up1, up2, up1, up2, up1, up2

def on_lang_filter(selected_lang):
    global GLOBAL_VOICES_CACHE
    if not selected_lang or selected_lang == "Todos os Idiomas":
        filtered = [f"{v['name']} ({v['language']} - {v.get('gender')})" if v.get('gender') else f"{v['name']} ({v['language']})" for v in GLOBAL_VOICES_CACHE]
        new_val = "Nenhuma (Fazer Upload)"
    else:
        filtered = [f"{v['name']} ({v['language']} - {v.get('gender')})" if v.get('gender') else f"{v['name']} ({v['language']})" for v in GLOBAL_VOICES_CACHE if v.get('language') == selected_lang]
        new_val = filtered[0] if filtered else "Nenhuma (Fazer Upload)"
    
    return gr.update(choices=["Nenhuma (Fazer Upload)"] + filtered, value=new_val)

def on_voice_select(selected_voice):
    if not selected_voice or selected_voice == "Nenhuma (Fazer Upload)":
        return None
    
    url = GLOBAL_VOICE_URLS.get(selected_voice)
    if not url: return None
    
    try:
        import tempfile
        import urllib.request
        tmp_file = tempfile.NamedTemporaryFile(delete=False, suffix=".wav")
        urllib.request.urlretrieve(url, tmp_file.name)
        return tmp_file.name
    except:
        pass
    return None

def save_new_voice_url(name, lang, audio_url):
    if not audio_url:
        return "Erro: Falta link de áudio"
    try:
        if fb_client.create_voice(name, lang, audio_url):
            return "Voz cadastrada com sucesso!"
        else:
            return "Falha ao salvar no banco."
    except Exception as e:
        return f"Erro: {str(e)}"


