                import shutil
                extracted_path = None
                if isinstance(file_path, str): extracted_path = file_path
                elif hasattr(file_path, "name"): extracted_path = file_path.name
                elif isinstance(file_path, dict) and "name" in file_path: extracted_path = file_path["name"]
                
                if extracted_path:
                    if not hasattr(add_to_history, "seen"): add_to_history.seen = set()
